module license_renewal(\n    input wire clk,\n    input wire rst_n,\n    input wire start,\n    input wire [3:0] n,\n    input wire [7:0] s1,\n    input wire [7:0] s2,\n    input wire [7:0] t0,\n    input wire [7:0] t1,\n    input wire [7:0] t2,\n    input wire [7:0] t3,\n    input wire [7:0] t4,\n    input wire [7:0] t5,\n    input wire [7:0] t6,\n    input wire [7:0] t7,\n    output reg [3:0] max_count,\n    output reg done\n);\n    localparam [2:0] IDLE = 3'd0;\n    localparam [2:0] INIT = 3'd1;\n    localparam [2:0] SETUP_SIM = 3'd2;\n    localparam [2:0] CHECK_CUSTOMER = 3'd3;\n    localparam [2:0] NEXT_ASSIGNMENT = 3'd4;\n    localparam [2:0] DONE = 3'd5;\n    reg [2:0] state;\n    reg [8:0] assignment_counter;\n    reg [8:0] max_assignment;\n    reg [3:0] n_reg;\n    reg [7:0] s1_reg, s2_reg;\n    reg [7:0] t_reg0, t_reg1, t_reg2, t_reg3, t_reg4, t_reg5, t_reg6, t_reg7;\n    reg [3:0] customer_index;\n    reg [7:0] rem1, rem2;\n    reg [3:0] current_count;\n    integer i;\n    always @(posedge clk or negedge rst_n) begin\n        if (!rst_n) begin\n            state <= IDLE;\n            assignment_counter <= 9'd0;\n            max_assignment <= 9'd0;\n            n_reg <= 4'd0;\n            s1_reg <= 8'd0;\n            s2_reg <= 8'd0;\n            t_reg0 <= 8'd0;\n            t_reg1 <= 8'd0;\n            t_reg2 <= 8'd0;\n            t_reg3 <= 8'd0;\n            t_reg4 <= 8'd0;\n            t_reg5 <= 8'd0;\n            t_reg6 <= 8'd0;\n            t_reg7 <= 8'd0;\n            customer_index <= 4'd0;\n            rem1 <= 8'd0;\n            rem2 <= 8'd0;\n            current_count <= 4'd0;\n            max_count <= 4'd0;\n            done <= 1'b0;\n        end else begin\n            case (state)\n                IDLE: begin\n                    done <= 1'b0;\n                    if (start) begin\n                        state <= INIT;\n                    end\n                end\n                INIT: begin\n                    n_reg <= n;\n                    s1_reg <= s1;\n                    s2_reg <= s2;\n                    t_reg0 <= t0;\n                    t_reg1 <= t1;\n                    t_reg2 <= t2;\n                    t_reg3 <= t3;\n                    t_reg4 <= t4;\n                    t_reg5 <= t5;\n                    t_reg6 <= t6;\n                    t_reg7 <= t7;\n                    max_assignment <= (9'd1 << n) - 9'd1;\n                    assignment_counter <= 9'd0;\n                    max_count <= 4'd0;\n                    state <= SETUP_SIM;\n                end\n                SETUP_SIM: begin\n                    customer_index <= 4'd0;\n                    rem1 <= s1_reg;\n                    rem2 <= s2_reg;\n                    current_count <= 4'd0;\n                    state <= CHECK_CUSTOMER;\n                end\n                CHECK_CUSTOMER: begin\n                    if (customer_index >= n_reg) begin\n                        if (current_count > max_count) begin\n                            max_count <= current_count;\n                        end\n                        state <= NEXT_ASSIGNMENT;\n                    end else begin\n                        if (assignment_counter[customer_index] == 1'b0) begin\n                            if (t_reg0 <= rem1) begin\n                                rem1 <= rem1 - t_reg0;\n                                current_count <= current_count + 4'd1;\n                                customer_index <= customer_index + 4'd1;\n                            end else begin\n                                if (current_count > max_count) begin\n                                    max_count <= current_count;\n                                end\n                                state <= NEXT_ASSIGNMENT;\n                            end\n                        end else begin\n                            if (t_reg0 <= rem2) begin\n                                rem2 <= rem2 - t_reg0;\n                                current_count <= current_count + 4'd1;\n                                customer_index <= customer_index + 4'd1;\n                            end else begin\n                                if (current_count > max_count) begin\n                                    max_count <= current_count;\n                                end\n                                state <= NEXT_ASSIGNMENT;\n                            end\n                        end\n                    end\n                end\n                NEXT_ASSIGNMENT: begin\n                    if (assignment_counter + 9'd1 <= max_assignment) begin\n                        assignment_counter <= assignment_counter + 9'd1;\n                        state <= SETUP_SIM;\n                    end else begin\n                        state <= DONE;\n                    end\n                end\n                DONE: begin\n                    done <= 1'b1;\n                end\n                default: state <= IDLE;\n            endcase\n        end\n    end\nendmodule